<?php require_once __DIR__.'/../includes/admin-auth.php';require_admin(['super_admin','event_admin']);$pageTitle='Participants';$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT u.id,u.name,u.email,u.mobile,u.created_at,COUNT(CASE WHEN r.status='valid' THEN 1 END) registrations FROM users u LEFT JOIN registrations r ON r.user_id=u.id WHERE u.name LIKE ? OR u.email LIKE ? OR u.mobile LIKE ? GROUP BY u.id ORDER BY u.created_at DESC LIMIT 300");$s->execute(["%$q%","%$q%","%$q%"]);$users=$s->fetchAll();require __DIR__.'/../includes/admin-layout.php'; ?><div class="panel"><form class="d-flex gap-2 mb-3" data-validate novalidate data-no-lock><input class="form-control" maxlength="80" name="q" value="<?=e($q)?>" placeholder="Search name, email, mobile"><button class="btn btn-primary">Search</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Participant</th><th>Mobile</th><th>Joined</th><th>Valid registrations</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?=e($u['name'])?></strong><div class="small muted"><?=e($u['email'])?></div></td><td><?=e($u['mobile'])?></td><td><?=e(date('M j, Y',strtotime($u['created_at'])))?></td><td><?=e($u['registrations'])?></td></tr><?php endforeach; ?><?php if(!$users): ?><tr><td colspan="4" class="text-center muted">No participants found.</td></tr><?php endif; ?></tbody></table></div><p class="small muted mb-0">Showing up to 300 matching participants.</p></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
